import json

with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

doc = data['document']
pages = doc.get('pages', [])
print(f"Number of pages: {len(pages)}")

# Look at first few pages
for i, page in enumerate(pages[:5]):
    print(f"\nPage {i}: id={page.get('id')}")
    content = page.get('content', [])
    if isinstance(content, list) and len(content) > 0:
        # Look at first few content elements
        for j, elem in enumerate(content[:3]):
            if isinstance(elem, dict):
                print(f"  Element {j}: {list(elem.keys())}")
                # Look for 'text' field
                if 'text' in elem:
                    print(f"    Text: {elem['text'][:100]}...")
                if 'description' in elem:
                    print(f"    Description: {str(elem['description'])[:100]}...")

# Let's look for page with individual income tax data
# The page number should be in the id
for page in pages:
    content = page.get('content', [])
    if isinstance(content, list):
        for elem in content:
            if isinstance(elem, dict) and 'text' in elem:
                text = elem.get('text', '')
                if 'Individual' in text and '1929' in text:
                    print(f"\nFound relevant page: {page.get('id')}")
                    print(f"Text sample: {text[:500]}")
                    break
